var _STD='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
var _URL='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
function b64Utf8Bytes(str){
  var out=[];
  for(var i=0;i<str.length;i++){
    var c=str.codePointAt(i);
    if(c>0xFFFF) i++;
    if(c<0x80) out.push(c);
    else if(c<0x800){ out.push(0xC0|(c>>6),0x80|(c&63)); }
    else if(c<0x10000){ out.push(0xE0|(c>>12),0x80|((c>>6)&63),0x80|(c&63)); }
    else { out.push(0xF0|(c>>18),0x80|((c>>12)&63),0x80|((c>>6)&63),0x80|(c&63)); }
  }
  return out;
}
function b64BytesToUtf8(bytes){
  var out='',i=0;
  while(i<bytes.length){
    var b=bytes[i];
    if(b<0x80){ out+=String.fromCharCode(b); i++; }
    else if(b>=0xC0&&b<0xE0){ out+=String.fromCharCode(((b&31)<<6)|(bytes[i+1]&63)); i+=2; }
    else if(b>=0xE0&&b<0xF0){ out+=String.fromCharCode(((b&15)<<12)|((bytes[i+1]&63)<<6)|(bytes[i+2]&63)); i+=3; }
    else {
      var cp=((b&7)<<18)|((bytes[i+1]&63)<<12)|((bytes[i+2]&63)<<6)|(bytes[i+3]&63);
      out+=String.fromCodePoint(cp); i+=4;
    }
  }
  return out;
}
function b64EncodeBytes(bytes, opts){
  opts=opts||{};
  var alpha=opts.urlSafe?_URL:_STD;
  var pad=opts.pad===undefined?true:!!opts.pad;
  var out='';
  for(var i=0;i<bytes.length;i+=3){
    var b0=bytes[i], b1=i+1<bytes.length?bytes[i+1]:0, b2=i+2<bytes.length?bytes[i+2]:0;
    var trip=(b0<<16)|(b1<<8)|b2;
    out+=alpha[(trip>>18)&63]+alpha[(trip>>12)&63];
    out+= i+1<bytes.length ? alpha[(trip>>6)&63] : (pad?'=':'');
    out+= i+2<bytes.length ? alpha[trip&63] : (pad?'=':'');
  }
  return out;
}
function b64DecodeToBytes(s){
  s=String(s).replace(/[\r\n\s]/g,'').replace(/=+$/,'');
  if(!/^[A-Za-z0-9+\/\-_]*$/.test(s)) return {value:null, error:'含非法字符'};
  if(s.length%4===1) return {value:null, error:'长度非法（mod 4 == 1）'};
  var out=[];
  for(var i=0;i<s.length;i+=4){
    var n=0, have=0;
    for(var j=0;j<4;j++){
      var ch=s[i+j];
      var v = ch===undefined ? 0 : (_STD.indexOf(ch)>=0?_STD.indexOf(ch):_URL.indexOf(ch));
      if(ch!==undefined){ if(v<0) return {value:null, error:'非法字符 '+ch}; have++; }
      n=(n<<6)|(v<0?0:v);
    }
    out.push((n>>16)&255);
    if(have>2) out.push((n>>8)&255);
    if(have>3) out.push(n&255);
  }
  return {value:out, error:null};
}
function b64Encode(str, opts){ return b64EncodeBytes(b64Utf8Bytes(str), opts); }
function b64Decode(s){
  var r=b64DecodeToBytes(s);
  if(r.error) return r;
  try { return {value:b64BytesToUtf8(r.value), error:null}; }
  catch(e){ return {value:null, error:'UTF-8 解码失败'}; }
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { b64Encode:b64Encode, b64Decode:b64Decode,
    b64EncodeBytes:b64EncodeBytes, b64DecodeToBytes:b64DecodeToBytes, b64Utf8Bytes:b64Utf8Bytes };
}
if (typeof window !== 'undefined') {
  window.Base64ForgePure = { b64Encode:b64Encode, b64Decode:b64Decode,
    b64EncodeBytes:b64EncodeBytes, b64DecodeToBytes:b64DecodeToBytes };
}
